css:
[data-workspace-area="conversation"] {
  background: linear-gradient(90deg, rgb(10 7 16 / .92) 0, rgb(10 7 16 / .9) calc(50% - 430px), rgb(10 7 16 / .78) calc(50% - 350px), rgb(10 7 16 / .74) 50%, rgb(10 7 16 / 0.739) calc(50% + 35px), rgb(10 7 16 / 0.734) calc(50% + 70px), rgb(10 7 16 / 0.727) calc(50% + 105px), rgb(10 7 16 / 0.717) calc(50% + 140px), rgb(10 7 16 / 0.703) calc(50% + 175px), rgb(10 7 16 / 0.688) calc(50% + 210px), rgb(10 7 16 / 0.669) calc(50% + 245px), rgb(10 7 16 / 0.635) calc(50% + 280px), rgb(10 7 16 / 0.541) calc(50% + 315px), rgb(10 7 16 / 0.414) calc(50% + 350px), rgb(10 7 16 / 0.286) calc(50% + 385px), rgb(10 7 16 / 0.184) calc(50% + 420px), rgb(10 7 16 / 0.090) calc(50% + 455px), rgb(10 7 16 / 0.000) calc(50% + 490px)), var(--theme-background-image) right center / auto 100% no-repeat, #0A0710 !important;
}
.messages-timeline-scroll { background: transparent !important; }
[data-user-message-bubble] { border: 1px solid #FA0F46; border-radius: 2px !important; box-shadow: 3px 3px 0 #FA0F46; }
.chat-markdown h1, .chat-markdown h2, .chat-markdown h3, .chat-markdown h4 { color: #FF8FB0 !important; }
.chat-markdown strong { color: #6EE7A4 !important;  }
.chat-markdown a { color: #6EE7A4 !important; text-decoration-color: #FA0F46 !important; }
.chat-markdown li::marker { color: #08F868; }
.chat-markdown :not(pre) > code { color: #6EE7A4 !important; background: #0B2E1E !important; border-radius: 2px !important; }
.chat-markdown blockquote { border-left-color: #08F868 !important; }
.chat-markdown hr { border-color: #0E8F4E !important; }
.chat-markdown th { color: #FF8FB0 !important; }
.chat-markdown-codeblock { border-left: 2px solid #08F868; border-radius: 2px !important; box-shadow: 3px 3px 0 #FA0F46; }
[data-slot="composer-host"] { border-color: #0E8F4E !important; border-radius: 3px !important; box-shadow: 4px 4px 0 #FA0F46; }
[data-slot="button"], [data-slot="input"], [data-slot="select-trigger"], [data-slot="menu-popup"], [data-slot="popover-popup"], [data-slot="dialog-popup"], [data-slot="tooltip-popup"] { border-radius: 2px !important; }
[data-thread-item] { border-radius: 2px !important; }
::-webkit-scrollbar-thumb { background: #0E8F4E; }
::-webkit-scrollbar-thumb:hover { background: #08F868; }
svg.lucide { stroke-linecap: square; stroke-linejoin: miter; }

/* Sidebar labels: replace green with the character pink, scoped to the sidebar only. */
[data-slot="sidebar"] {
  --app-theme-secondary-label: #FF8FB0; --secondary-label: #FF8FB0; --contrast-secondary-label: #FF8FB0;
  --app-theme-icon-muted: #FF8FB0; --icon-muted: #FF8FB0; --contrast-icon-muted: #FF8FB0;
}
[data-slot="sidebar"] .text-secondary-label, [data-slot="sidebar"] .text-icon-muted { color: #FF8FB0 !important; }

/* Keeps text crisp over the lighter blend. */
.chat-markdown { text-shadow: 0 0 3px rgb(10 7 16 / .85), 0 1px 2px rgb(10 7 16 / .7); }
.chat-markdown-codeblock, .chat-markdown-codeblock * { text-shadow: none; }
